import React from "react";
import "./DailyWeather.css";


export default function DailyWeather (props){


    return (<div className= "DailyWeather">
        <div className="row">
            <div className="col">
                <div className="DailyWeather-day">Thu</div>
                <div className="DailyWeather-Icon">{props.iconURL}</div>
                <div className="DailyWeather-Temperature">
                    <span className="max">20º</span>
                    <span className="min">10º</span>
                </div>
                 </div>











        </div>
    </div>);

}
